CREATE TABLE eam_inspection_type (id BIGINT NOT NULL,tenant_id BIGINT NOT NULL,code VARCHAR(64) NOT NULL,name VARCHAR(150) NOT NULL,department_id BIGINT NULL,creator_id BIGINT NOT NULL,row_version INT NOT NULL DEFAULT 0,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,`enabled` TINYINT NOT NULL COMMENT 'enabled',`remark` TEXT NOT NULL COMMENT 'remark',`period_count` INT NOT NULL COMMENT 'period',`period_unit` VARCHAR(8) NOT NULL COMMENT 'unit',`sort_order` INT NOT NULL COMMENT 'sortOrder',PRIMARY KEY(id),UNIQUE KEY(tenant_id,code),INDEX(tenant_id,department_id,created_at,id));

INSERT INTO eam_inspection_type (id,tenant_id,code,name,department_id,creator_id,row_version,created_at,updated_at,`enabled`,`remark`,`period_count`,`period_unit`,`sort_order`) SELECT id,tenant_id,code,name,department_id,creator_id,row_version,created_at,updated_at,CASE WHEN NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(d.payload,'$.enabled')),'null'),'') IN ('true','1') THEN 1 WHEN NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(d.payload,'$.enabled')),'null'),'') IN ('false','0') THEN 0 ELSE 1 END,COALESCE(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(d.payload,'$.remark')),'null'),''),''),COALESCE(CAST(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(d.payload,'$.period')),'null'),'') AS SIGNED),1),COALESCE(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(d.payload,'$.unit')),'null'),''),'日'),COALESCE(CAST(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(d.payload,'$.sortOrder')),'null'),'') AS SIGNED),0) FROM eam_inspection_definition d WHERE kind='types';

CREATE TABLE eam_inspection_standard (id BIGINT NOT NULL,tenant_id BIGINT NOT NULL,code VARCHAR(64) NOT NULL,name VARCHAR(150) NOT NULL,department_id BIGINT NULL,creator_id BIGINT NOT NULL,row_version INT NOT NULL DEFAULT 0,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,`enabled` TINYINT NOT NULL COMMENT 'enabled',`remark` TEXT NOT NULL COMMENT 'remark',`requirement` TEXT NOT NULL COMMENT 'requirement',PRIMARY KEY(id),UNIQUE KEY(tenant_id,code),INDEX(tenant_id,department_id,created_at,id));

INSERT INTO eam_inspection_standard (id,tenant_id,code,name,department_id,creator_id,row_version,created_at,updated_at,`enabled`,`remark`,`requirement`) SELECT id,tenant_id,code,name,department_id,creator_id,row_version,created_at,updated_at,CASE WHEN NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(d.payload,'$.enabled')),'null'),'') IN ('true','1') THEN 1 WHEN NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(d.payload,'$.enabled')),'null'),'') IN ('false','0') THEN 0 ELSE 1 END,COALESCE(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(d.payload,'$.remark')),'null'),''),''),COALESCE(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(d.payload,'$.requirement')),'null'),''),'') FROM eam_inspection_definition d WHERE kind='standards';

CREATE TABLE eam_inspection_daily_plan (id BIGINT NOT NULL,tenant_id BIGINT NOT NULL,code VARCHAR(64) NOT NULL,name VARCHAR(150) NOT NULL,department_id BIGINT NULL,creator_id BIGINT NOT NULL,row_version INT NOT NULL DEFAULT 0,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,`enabled` TINYINT NOT NULL COMMENT 'enabled',`remark` TEXT NOT NULL COMMENT 'remark',`type_id` BIGINT NULL COMMENT 'typeId',`review_mode` VARCHAR(24) NOT NULL COMMENT 'reviewMode',`start_date` DATE NULL COMMENT 'startDate',`end_date` DATE NULL COMMENT 'endDate',`valid_duration` DECIMAL(18,2) NOT NULL COMMENT 'validHours',`advance_duration` DECIMAL(18,2) NOT NULL COMMENT 'advanceHours',`remind_duration` DECIMAL(18,2) NOT NULL COMMENT 'remindHours',`expire_remind_duration` DECIMAL(18,2) NOT NULL COMMENT 'expireRemindHours',`valid_unit` VARCHAR(8) NOT NULL COMMENT 'validUnit',`advance_unit` VARCHAR(8) NOT NULL COMMENT 'advanceUnit',`remind_unit` VARCHAR(8) NOT NULL COMMENT 'remindUnit',`expire_remind_unit` VARCHAR(8) NOT NULL COMMENT 'expireRemindUnit',`scan_mode` VARCHAR(40) NOT NULL COMMENT 'scanMode',`only_abnormal` TINYINT NOT NULL COMMENT 'onlyAbnormal',`random_photo_count` INT NOT NULL COMMENT 'randomPhotoCount',`allow_late` TINYINT NOT NULL COMMENT 'allowLate',`person_mode` VARCHAR(40) NOT NULL COMMENT 'personMode',`skip_unstaffed` TINYINT NOT NULL COMMENT 'skipUnstaffed',`rest_cycle` VARCHAR(8) NOT NULL COMMENT 'restCycle',`use_shift_end` TINYINT NOT NULL COMMENT 'useShiftEnd',PRIMARY KEY(id),UNIQUE KEY(tenant_id,code),INDEX(tenant_id,department_id,created_at,id));

INSERT INTO eam_inspection_daily_plan (id,tenant_id,code,name,department_id,creator_id,row_version,created_at,updated_at,`enabled`,`remark`,`type_id`,`review_mode`,`start_date`,`end_date`,`valid_duration`,`advance_duration`,`remind_duration`,`expire_remind_duration`,`valid_unit`,`advance_unit`,`remind_unit`,`expire_remind_unit`,`scan_mode`,`only_abnormal`,`random_photo_count`,`allow_late`,`person_mode`,`skip_unstaffed`,`rest_cycle`,`use_shift_end`) SELECT id,tenant_id,code,name,department_id,creator_id,row_version,created_at,updated_at,CASE WHEN NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(d.payload,'$.enabled')),'null'),'') IN ('true','1') THEN 1 WHEN NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(d.payload,'$.enabled')),'null'),'') IN ('false','0') THEN 0 ELSE 1 END,COALESCE(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(d.payload,'$.remark')),'null'),''),''),COALESCE(d.type_id,COALESCE(CAST(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(d.payload,'$.typeId')),'null'),'') AS SIGNED),NULL)),COALESCE(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(d.payload,'$.reviewMode')),'null'),''),'无需审核'),COALESCE(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(d.payload,'$.startDate')),'null'),''),NULL),COALESCE(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(d.payload,'$.endDate')),'null'),''),NULL),COALESCE(CAST(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(d.payload,'$.validHours')),'null'),'') AS DECIMAL(30,8)),1),COALESCE(CAST(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(d.payload,'$.advanceHours')),'null'),'') AS DECIMAL(30,8)),0),COALESCE(CAST(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(d.payload,'$.remindHours')),'null'),'') AS DECIMAL(30,8)),0),COALESCE(CAST(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(d.payload,'$.expireRemindHours')),'null'),'') AS DECIMAL(30,8)),0),COALESCE(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(d.payload,'$.validUnit')),'null'),''),'时'),COALESCE(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(d.payload,'$.advanceUnit')),'null'),''),'时'),COALESCE(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(d.payload,'$.remindUnit')),'null'),''),'时'),COALESCE(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(d.payload,'$.expireRemindUnit')),'null'),''),'时'),COALESCE(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(d.payload,'$.scanMode')),'null'),''),'无需扫码'),CASE WHEN NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(d.payload,'$.onlyAbnormal')),'null'),'') IN ('true','1') THEN 1 WHEN NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(d.payload,'$.onlyAbnormal')),'null'),'') IN ('false','0') THEN 0 ELSE 0 END,COALESCE(CAST(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(d.payload,'$.randomPhotoCount')),'null'),'') AS SIGNED),0),CASE WHEN NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(d.payload,'$.allowLate')),'null'),'') IN ('true','1') THEN 1 WHEN NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(d.payload,'$.allowLate')),'null'),'') IN ('false','0') THEN 0 ELSE 0 END,COALESCE(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(d.payload,'$.personMode')),'null'),''),'指定负责人'),CASE WHEN NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(d.payload,'$.skipUnstaffed')),'null'),'') IN ('true','1') THEN 1 WHEN NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(d.payload,'$.skipUnstaffed')),'null'),'') IN ('false','0') THEN 0 ELSE 0 END,COALESCE(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(d.payload,'$.restCycle')),'null'),''),'按周'),CASE WHEN NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(d.payload,'$.useShiftEnd')),'null'),'') IN ('true','1') THEN 1 WHEN NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(d.payload,'$.useShiftEnd')),'null'),'') IN ('false','0') THEN 0 ELSE 0 END FROM eam_inspection_definition d WHERE kind='daily-plans';

CREATE TABLE eam_inspection_periodic_plan (id BIGINT NOT NULL,tenant_id BIGINT NOT NULL,code VARCHAR(64) NOT NULL,name VARCHAR(150) NOT NULL,department_id BIGINT NULL,creator_id BIGINT NOT NULL,row_version INT NOT NULL DEFAULT 0,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,`enabled` TINYINT NOT NULL COMMENT 'enabled',`remark` TEXT NOT NULL COMMENT 'remark',`type_id` BIGINT NULL COMMENT 'typeId',`review_mode` VARCHAR(24) NOT NULL COMMENT 'reviewMode',`start_date` DATE NULL COMMENT 'startDate',`end_date` DATE NULL COMMENT 'endDate',`valid_duration` DECIMAL(18,2) NOT NULL COMMENT 'validHours',`advance_duration` DECIMAL(18,2) NOT NULL COMMENT 'advanceHours',`remind_duration` DECIMAL(18,2) NOT NULL COMMENT 'remindHours',`expire_remind_duration` DECIMAL(18,2) NOT NULL COMMENT 'expireRemindHours',`valid_unit` VARCHAR(8) NOT NULL COMMENT 'validUnit',`advance_unit` VARCHAR(8) NOT NULL COMMENT 'advanceUnit',`remind_unit` VARCHAR(8) NOT NULL COMMENT 'remindUnit',`expire_remind_unit` VARCHAR(8) NOT NULL COMMENT 'expireRemindUnit',`scan_mode` VARCHAR(40) NOT NULL COMMENT 'scanMode',`only_abnormal` TINYINT NOT NULL COMMENT 'onlyAbnormal',`random_photo_count` INT NOT NULL COMMENT 'randomPhotoCount',`allow_late` TINYINT NOT NULL COMMENT 'allowLate',`period_count` INT NOT NULL COMMENT 'period',`period_unit` VARCHAR(8) NOT NULL COMMENT 'unit',`next_at` DATETIME NULL COMMENT 'nextAt',PRIMARY KEY(id),UNIQUE KEY(tenant_id,code),INDEX(tenant_id,department_id,created_at,id));

INSERT INTO eam_inspection_periodic_plan (id,tenant_id,code,name,department_id,creator_id,row_version,created_at,updated_at,`enabled`,`remark`,`type_id`,`review_mode`,`start_date`,`end_date`,`valid_duration`,`advance_duration`,`remind_duration`,`expire_remind_duration`,`valid_unit`,`advance_unit`,`remind_unit`,`expire_remind_unit`,`scan_mode`,`only_abnormal`,`random_photo_count`,`allow_late`,`period_count`,`period_unit`,`next_at`) SELECT id,tenant_id,code,name,department_id,creator_id,row_version,created_at,updated_at,CASE WHEN NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(d.payload,'$.enabled')),'null'),'') IN ('true','1') THEN 1 WHEN NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(d.payload,'$.enabled')),'null'),'') IN ('false','0') THEN 0 ELSE 1 END,COALESCE(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(d.payload,'$.remark')),'null'),''),''),COALESCE(d.type_id,COALESCE(CAST(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(d.payload,'$.typeId')),'null'),'') AS SIGNED),NULL)),COALESCE(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(d.payload,'$.reviewMode')),'null'),''),'无需审核'),COALESCE(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(d.payload,'$.startDate')),'null'),''),NULL),COALESCE(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(d.payload,'$.endDate')),'null'),''),NULL),COALESCE(CAST(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(d.payload,'$.validHours')),'null'),'') AS DECIMAL(30,8)),1),COALESCE(CAST(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(d.payload,'$.advanceHours')),'null'),'') AS DECIMAL(30,8)),0),COALESCE(CAST(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(d.payload,'$.remindHours')),'null'),'') AS DECIMAL(30,8)),0),COALESCE(CAST(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(d.payload,'$.expireRemindHours')),'null'),'') AS DECIMAL(30,8)),0),COALESCE(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(d.payload,'$.validUnit')),'null'),''),'时'),COALESCE(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(d.payload,'$.advanceUnit')),'null'),''),'时'),COALESCE(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(d.payload,'$.remindUnit')),'null'),''),'时'),COALESCE(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(d.payload,'$.expireRemindUnit')),'null'),''),'时'),COALESCE(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(d.payload,'$.scanMode')),'null'),''),'无需扫码'),CASE WHEN NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(d.payload,'$.onlyAbnormal')),'null'),'') IN ('true','1') THEN 1 WHEN NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(d.payload,'$.onlyAbnormal')),'null'),'') IN ('false','0') THEN 0 ELSE 0 END,COALESCE(CAST(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(d.payload,'$.randomPhotoCount')),'null'),'') AS SIGNED),0),CASE WHEN NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(d.payload,'$.allowLate')),'null'),'') IN ('true','1') THEN 1 WHEN NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(d.payload,'$.allowLate')),'null'),'') IN ('false','0') THEN 0 ELSE 0 END,COALESCE(CAST(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(d.payload,'$.period')),'null'),'') AS SIGNED),1),COALESCE(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(d.payload,'$.unit')),'null'),''),'日'),COALESCE(REPLACE(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(d.payload,'$.nextAt')),'null'),''),'T',' '),NULL) FROM eam_inspection_definition d WHERE kind='periodic-plans';

CREATE TABLE eam_inspection_standard_person (tenant_id BIGINT NOT NULL,parent_id BIGINT NOT NULL,role_code VARCHAR(16) NOT NULL,user_id BIGINT NOT NULL,sort_no INT NOT NULL,PRIMARY KEY(tenant_id,parent_id,role_code,user_id),INDEX(tenant_id,user_id),FOREIGN KEY(parent_id) REFERENCES eam_inspection_standard(id) ON DELETE CASCADE);

INSERT INTO eam_inspection_standard_person SELECT d.tenant_id,d.id,'owner',v.user_id,MIN(v.sort_no) FROM eam_inspection_definition d JOIN JSON_TABLE(COALESCE(JSON_EXTRACT(d.payload,'$.owners'),JSON_ARRAY()),'$[*]' COLUMNS(sort_no FOR ORDINALITY,user_id BIGINT PATH '$' ERROR ON ERROR)) v WHERE kind='standards' GROUP BY d.tenant_id,d.id,v.user_id;

INSERT INTO eam_inspection_standard_person SELECT d.tenant_id,d.id,'reviewer',v.user_id,MIN(v.sort_no) FROM eam_inspection_definition d JOIN JSON_TABLE(COALESCE(JSON_EXTRACT(d.payload,'$.reviewers'),JSON_ARRAY()),'$[*]' COLUMNS(sort_no FOR ORDINALITY,user_id BIGINT PATH '$' ERROR ON ERROR)) v WHERE kind='standards' GROUP BY d.tenant_id,d.id,v.user_id;

CREATE TABLE eam_inspection_daily_plan_person (tenant_id BIGINT NOT NULL,parent_id BIGINT NOT NULL,role_code VARCHAR(16) NOT NULL,user_id BIGINT NOT NULL,sort_no INT NOT NULL,PRIMARY KEY(tenant_id,parent_id,role_code,user_id),INDEX(tenant_id,user_id),FOREIGN KEY(parent_id) REFERENCES eam_inspection_daily_plan(id) ON DELETE CASCADE);

INSERT INTO eam_inspection_daily_plan_person SELECT d.tenant_id,d.id,'owner',v.user_id,MIN(v.sort_no) FROM eam_inspection_definition d JOIN JSON_TABLE(COALESCE(JSON_EXTRACT(d.payload,'$.owners'),JSON_ARRAY()),'$[*]' COLUMNS(sort_no FOR ORDINALITY,user_id BIGINT PATH '$' ERROR ON ERROR)) v WHERE kind='daily-plans' GROUP BY d.tenant_id,d.id,v.user_id;

INSERT INTO eam_inspection_daily_plan_person SELECT d.tenant_id,d.id,'reviewer',v.user_id,MIN(v.sort_no) FROM eam_inspection_definition d JOIN JSON_TABLE(COALESCE(JSON_EXTRACT(d.payload,'$.reviewers'),JSON_ARRAY()),'$[*]' COLUMNS(sort_no FOR ORDINALITY,user_id BIGINT PATH '$' ERROR ON ERROR)) v WHERE kind='daily-plans' GROUP BY d.tenant_id,d.id,v.user_id;

CREATE TABLE eam_inspection_periodic_plan_person (tenant_id BIGINT NOT NULL,parent_id BIGINT NOT NULL,role_code VARCHAR(16) NOT NULL,user_id BIGINT NOT NULL,sort_no INT NOT NULL,PRIMARY KEY(tenant_id,parent_id,role_code,user_id),INDEX(tenant_id,user_id),FOREIGN KEY(parent_id) REFERENCES eam_inspection_periodic_plan(id) ON DELETE CASCADE);

INSERT INTO eam_inspection_periodic_plan_person SELECT d.tenant_id,d.id,'owner',v.user_id,MIN(v.sort_no) FROM eam_inspection_definition d JOIN JSON_TABLE(COALESCE(JSON_EXTRACT(d.payload,'$.owners'),JSON_ARRAY()),'$[*]' COLUMNS(sort_no FOR ORDINALITY,user_id BIGINT PATH '$' ERROR ON ERROR)) v WHERE kind='periodic-plans' GROUP BY d.tenant_id,d.id,v.user_id;

INSERT INTO eam_inspection_periodic_plan_person SELECT d.tenant_id,d.id,'reviewer',v.user_id,MIN(v.sort_no) FROM eam_inspection_definition d JOIN JSON_TABLE(COALESCE(JSON_EXTRACT(d.payload,'$.reviewers'),JSON_ARRAY()),'$[*]' COLUMNS(sort_no FOR ORDINALITY,user_id BIGINT PATH '$' ERROR ON ERROR)) v WHERE kind='periodic-plans' GROUP BY d.tenant_id,d.id,v.user_id;

CREATE TABLE eam_inspection_standard_equipment (tenant_id BIGINT NOT NULL,standard_id BIGINT NOT NULL,equipment_id BIGINT NOT NULL,sort_no INT NOT NULL,PRIMARY KEY(tenant_id,standard_id,equipment_id),INDEX(tenant_id,equipment_id),FOREIGN KEY(standard_id) REFERENCES eam_inspection_standard(id) ON DELETE CASCADE);

INSERT INTO eam_inspection_standard_equipment SELECT d.tenant_id,d.id,j.target_id,MIN(j.sort_no) FROM eam_inspection_definition d JOIN JSON_TABLE(COALESCE(JSON_EXTRACT(d.payload,'$.equipmentIds'),JSON_ARRAY()),'$[*]' COLUMNS(sort_no FOR ORDINALITY,target_id BIGINT PATH '$' ERROR ON ERROR)) j WHERE kind='standards' GROUP BY d.tenant_id,d.id,j.target_id;

CREATE TABLE eam_inspection_standard_category (tenant_id BIGINT NOT NULL,standard_id BIGINT NOT NULL,category_id BIGINT NOT NULL,sort_no INT NOT NULL,PRIMARY KEY(tenant_id,standard_id,category_id),INDEX(tenant_id,category_id),FOREIGN KEY(standard_id) REFERENCES eam_inspection_standard(id) ON DELETE CASCADE);

INSERT INTO eam_inspection_standard_category SELECT d.tenant_id,d.id,j.target_id,MIN(j.sort_no) FROM eam_inspection_definition d JOIN JSON_TABLE(COALESCE(JSON_EXTRACT(d.payload,'$.categoryIds'),JSON_ARRAY()),'$[*]' COLUMNS(sort_no FOR ORDINALITY,target_id BIGINT PATH '$' ERROR ON ERROR)) j WHERE kind='standards' GROUP BY d.tenant_id,d.id,j.target_id;

CREATE TABLE eam_inspection_category_label (tenant_id BIGINT NOT NULL,standard_id BIGINT NOT NULL,label_kind VARCHAR(16) NOT NULL,sort_no INT NOT NULL,name_snapshot VARCHAR(255) NOT NULL,PRIMARY KEY(tenant_id,standard_id,label_kind,sort_no),FOREIGN KEY(standard_id) REFERENCES eam_inspection_standard(id) ON DELETE CASCADE);

INSERT INTO eam_inspection_category_label SELECT d.tenant_id,d.id,'display',j.sort_no,j.name FROM eam_inspection_definition d JOIN JSON_TABLE(COALESCE(JSON_EXTRACT(d.payload,'$.categoryNames'),JSON_ARRAY()),'$[*]' COLUMNS(sort_no FOR ORDINALITY,name VARCHAR(255) PATH '$')) j WHERE kind='standards';

INSERT INTO eam_inspection_category_label SELECT d.tenant_id,d.id,'legacy',j.sort_no,j.name FROM eam_inspection_definition d JOIN JSON_TABLE(COALESCE(JSON_EXTRACT(d.payload,'$.legacyCategoryNames'),JSON_ARRAY()),'$[*]' COLUMNS(sort_no FOR ORDINALITY,name VARCHAR(255) PATH '$')) j WHERE kind='standards';

CREATE TABLE eam_inspection_standard_item (tenant_id BIGINT NOT NULL,standard_id BIGINT NOT NULL,item_key VARCHAR(128) NOT NULL,sort_no INT NOT NULL,`code` VARCHAR(64) NOT NULL COMMENT 'code',`name` VARCHAR(200) NOT NULL COMMENT 'name',`content` TEXT NOT NULL COMMENT 'content',`type_id` BIGINT NULL COMMENT 'typeId',`value_type` VARCHAR(16) NOT NULL COMMENT 'valueType',`lower_bound` DECIMAL(30,8) NULL COMMENT 'lower',`upper_bound` DECIMAL(30,8) NULL COMMENT 'upper',`required` TINYINT NOT NULL COMMENT 'required',`photo_required` TINYINT NOT NULL COMMENT 'photoRequired',`remark` TEXT NOT NULL COMMENT 'remark',PRIMARY KEY(tenant_id,standard_id,item_key),INDEX(tenant_id,type_id),FOREIGN KEY(standard_id) REFERENCES eam_inspection_standard(id) ON DELETE CASCADE);

INSERT INTO eam_inspection_standard_item SELECT d.tenant_id,d.id,JSON_UNQUOTE(JSON_EXTRACT(j.item,'$.id')),j.sort_no,COALESCE(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(j.item,'$.code')),'null'),''),''),COALESCE(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(j.item,'$.name')),'null'),''),''),COALESCE(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(j.item,'$.content')),'null'),''),''),COALESCE(CAST(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(j.item,'$.typeId')),'null'),'') AS SIGNED),NULL),COALESCE(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(j.item,'$.valueType')),'null'),''),'文本'),COALESCE(CAST(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(j.item,'$.lower')),'null'),'') AS DECIMAL(30,8)),NULL),COALESCE(CAST(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(j.item,'$.upper')),'null'),'') AS DECIMAL(30,8)),NULL),CASE WHEN NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(j.item,'$.required')),'null'),'') IN ('true','1') THEN 1 WHEN NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(j.item,'$.required')),'null'),'') IN ('false','0') THEN 0 ELSE 0 END,CASE WHEN NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(j.item,'$.photoRequired')),'null'),'') IN ('true','1') THEN 1 WHEN NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(j.item,'$.photoRequired')),'null'),'') IN ('false','0') THEN 0 ELSE 0 END,COALESCE(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(j.item,'$.remark')),'null'),''),'') FROM eam_inspection_definition d JOIN JSON_TABLE(COALESCE(JSON_EXTRACT(d.payload,'$.items'),JSON_ARRAY()),'$[*]' COLUMNS(sort_no FOR ORDINALITY,item JSON PATH '$')) j WHERE kind='standards';

CREATE TABLE eam_inspection_item_option (tenant_id BIGINT NOT NULL,standard_id BIGINT NOT NULL,item_key VARCHAR(128) NOT NULL,sort_no INT NOT NULL,option_value VARCHAR(500) NOT NULL,normal_value TINYINT NOT NULL,PRIMARY KEY(tenant_id,standard_id,item_key,sort_no),FOREIGN KEY(tenant_id,standard_id,item_key) REFERENCES eam_inspection_standard_item(tenant_id,standard_id,item_key) ON DELETE CASCADE);

INSERT INTO eam_inspection_item_option SELECT d.tenant_id,d.id,JSON_UNQUOTE(JSON_EXTRACT(j.item,'$.id')),v.sort_no,JSON_UNQUOTE(v.value),IF(JSON_CONTAINS(JSON_EXTRACT(j.item,'$.normalOptions'),v.value),1,0) FROM eam_inspection_definition d JOIN JSON_TABLE(COALESCE(JSON_EXTRACT(d.payload,'$.items'),JSON_ARRAY()),'$[*]' COLUMNS(item JSON PATH '$')) j JOIN JSON_TABLE(COALESCE(JSON_EXTRACT(j.item,'$.options'),JSON_ARRAY()),'$[*]' COLUMNS(sort_no FOR ORDINALITY,value JSON PATH '$')) v WHERE kind='standards';

CREATE TABLE eam_inspection_item_file (tenant_id BIGINT NOT NULL,standard_id BIGINT NOT NULL,item_key VARCHAR(128) NOT NULL,sort_no INT NOT NULL,file_id VARCHAR(64) NOT NULL,name_snapshot VARCHAR(255) NOT NULL,content_type VARCHAR(150) NOT NULL,size_bytes BIGINT NOT NULL,url_snapshot VARCHAR(1000) NOT NULL,PRIMARY KEY(tenant_id,standard_id,item_key,sort_no),FOREIGN KEY(tenant_id,standard_id,item_key) REFERENCES eam_inspection_standard_item(tenant_id,standard_id,item_key) ON DELETE CASCADE);

INSERT INTO eam_inspection_item_file SELECT d.tenant_id,d.id,JSON_UNQUOTE(JSON_EXTRACT(j.item,'$.id')),v.sort_no,JSON_UNQUOTE(JSON_EXTRACT(v.value,'$.id')),COALESCE(JSON_UNQUOTE(JSON_EXTRACT(v.value,'$.name')),''),COALESCE(JSON_UNQUOTE(JSON_EXTRACT(v.value,'$.contentType')),''),COALESCE(JSON_EXTRACT(v.value,'$.size'),0),COALESCE(JSON_UNQUOTE(JSON_EXTRACT(v.value,'$.url')),'') FROM eam_inspection_definition d JOIN JSON_TABLE(COALESCE(JSON_EXTRACT(d.payload,'$.items'),JSON_ARRAY()),'$[*]' COLUMNS(item JSON PATH '$')) j JOIN JSON_TABLE(COALESCE(JSON_EXTRACT(j.item,'$.references'),JSON_ARRAY()),'$[*]' COLUMNS(sort_no FOR ORDINALITY,value JSON PATH '$')) v WHERE kind='standards';

CREATE TABLE eam_inspection_daily_plan_device (tenant_id BIGINT NOT NULL,plan_id BIGINT NOT NULL,device_key VARCHAR(128) NOT NULL,equipment_id BIGINT NOT NULL,sort_no INT NOT NULL,PRIMARY KEY(tenant_id,plan_id,device_key),UNIQUE KEY(tenant_id,plan_id,equipment_id),INDEX(tenant_id,equipment_id),FOREIGN KEY(plan_id) REFERENCES eam_inspection_daily_plan(id) ON DELETE CASCADE);

INSERT INTO eam_inspection_daily_plan_device SELECT d.tenant_id,d.id,COALESCE(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(v.value,'$.key')),''),CAST(v.sort_no AS CHAR)),JSON_EXTRACT(v.value,'$.equipmentId'),v.sort_no FROM eam_inspection_definition d JOIN JSON_TABLE(COALESCE(JSON_EXTRACT(d.payload,'$.details'),JSON_ARRAY()),'$[*]' COLUMNS(sort_no FOR ORDINALITY,value JSON PATH '$')) v WHERE kind='daily-plans';

CREATE TABLE eam_inspection_daily_plan_device_person (tenant_id BIGINT NOT NULL,plan_id BIGINT NOT NULL,device_key VARCHAR(128) NOT NULL,role_code VARCHAR(16) NOT NULL,user_id BIGINT NOT NULL,sort_no INT NOT NULL,PRIMARY KEY(tenant_id,plan_id,device_key,role_code,user_id),FOREIGN KEY(tenant_id,plan_id,device_key) REFERENCES eam_inspection_daily_plan_device(tenant_id,plan_id,device_key) ON DELETE CASCADE);

INSERT INTO eam_inspection_daily_plan_device_person SELECT d.tenant_id,d.id,COALESCE(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(v.value,'$.key')),''),CAST(v.sort_no AS CHAR)),'owner',j.user_id,MIN(j.n) FROM eam_inspection_definition d JOIN JSON_TABLE(COALESCE(JSON_EXTRACT(d.payload,'$.details'),JSON_ARRAY()),'$[*]' COLUMNS(sort_no FOR ORDINALITY,value JSON PATH '$')) v JOIN JSON_TABLE(COALESCE(JSON_EXTRACT(v.value,'$.owners'),JSON_ARRAY()),'$[*]' COLUMNS(n FOR ORDINALITY,user_id BIGINT PATH '$')) j WHERE kind='daily-plans' GROUP BY d.tenant_id,d.id,COALESCE(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(v.value,'$.key')),''),CAST(v.sort_no AS CHAR)),j.user_id;

INSERT INTO eam_inspection_daily_plan_device_person SELECT d.tenant_id,d.id,COALESCE(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(v.value,'$.key')),''),CAST(v.sort_no AS CHAR)),'reviewer',j.user_id,MIN(j.n) FROM eam_inspection_definition d JOIN JSON_TABLE(COALESCE(JSON_EXTRACT(d.payload,'$.details'),JSON_ARRAY()),'$[*]' COLUMNS(sort_no FOR ORDINALITY,value JSON PATH '$')) v JOIN JSON_TABLE(COALESCE(JSON_EXTRACT(v.value,'$.reviewers'),JSON_ARRAY()),'$[*]' COLUMNS(n FOR ORDINALITY,user_id BIGINT PATH '$')) j WHERE kind='daily-plans' GROUP BY d.tenant_id,d.id,COALESCE(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(v.value,'$.key')),''),CAST(v.sort_no AS CHAR)),j.user_id;

CREATE TABLE eam_inspection_daily_plan_device_project (tenant_id BIGINT NOT NULL,plan_id BIGINT NOT NULL,device_key VARCHAR(128) NOT NULL,standard_id BIGINT NOT NULL,item_key VARCHAR(128) NOT NULL,sort_no INT NOT NULL,PRIMARY KEY(tenant_id,plan_id,device_key,standard_id,item_key),FOREIGN KEY(tenant_id,plan_id,device_key) REFERENCES eam_inspection_daily_plan_device(tenant_id,plan_id,device_key) ON DELETE CASCADE);

INSERT INTO eam_inspection_daily_plan_device_project SELECT d.tenant_id,d.id,COALESCE(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(v.value,'$.key')),''),CAST(v.sort_no AS CHAR)),j.standard_id,j.item_key,MIN(j.n) FROM eam_inspection_definition d JOIN JSON_TABLE(COALESCE(JSON_EXTRACT(d.payload,'$.details'),JSON_ARRAY()),'$[*]' COLUMNS(sort_no FOR ORDINALITY,value JSON PATH '$')) v JOIN JSON_TABLE(COALESCE(JSON_EXTRACT(v.value,'$.projectRefs'),JSON_ARRAY()),'$[*]' COLUMNS(n FOR ORDINALITY,standard_id BIGINT PATH '$.standardId',item_key VARCHAR(128) PATH '$.itemId')) j WHERE kind='daily-plans' GROUP BY d.tenant_id,d.id,COALESCE(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(v.value,'$.key')),''),CAST(v.sort_no AS CHAR)),j.standard_id,j.item_key;

CREATE TABLE eam_inspection_periodic_plan_device (tenant_id BIGINT NOT NULL,plan_id BIGINT NOT NULL,device_key VARCHAR(128) NOT NULL,equipment_id BIGINT NOT NULL,sort_no INT NOT NULL,PRIMARY KEY(tenant_id,plan_id,device_key),UNIQUE KEY(tenant_id,plan_id,equipment_id),INDEX(tenant_id,equipment_id),FOREIGN KEY(plan_id) REFERENCES eam_inspection_periodic_plan(id) ON DELETE CASCADE);

INSERT INTO eam_inspection_periodic_plan_device SELECT d.tenant_id,d.id,COALESCE(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(v.value,'$.key')),''),CAST(v.sort_no AS CHAR)),JSON_EXTRACT(v.value,'$.equipmentId'),v.sort_no FROM eam_inspection_definition d JOIN JSON_TABLE(COALESCE(JSON_EXTRACT(d.payload,'$.details'),JSON_ARRAY()),'$[*]' COLUMNS(sort_no FOR ORDINALITY,value JSON PATH '$')) v WHERE kind='periodic-plans';

CREATE TABLE eam_inspection_periodic_plan_device_person (tenant_id BIGINT NOT NULL,plan_id BIGINT NOT NULL,device_key VARCHAR(128) NOT NULL,role_code VARCHAR(16) NOT NULL,user_id BIGINT NOT NULL,sort_no INT NOT NULL,PRIMARY KEY(tenant_id,plan_id,device_key,role_code,user_id),FOREIGN KEY(tenant_id,plan_id,device_key) REFERENCES eam_inspection_periodic_plan_device(tenant_id,plan_id,device_key) ON DELETE CASCADE);

INSERT INTO eam_inspection_periodic_plan_device_person SELECT d.tenant_id,d.id,COALESCE(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(v.value,'$.key')),''),CAST(v.sort_no AS CHAR)),'owner',j.user_id,MIN(j.n) FROM eam_inspection_definition d JOIN JSON_TABLE(COALESCE(JSON_EXTRACT(d.payload,'$.details'),JSON_ARRAY()),'$[*]' COLUMNS(sort_no FOR ORDINALITY,value JSON PATH '$')) v JOIN JSON_TABLE(COALESCE(JSON_EXTRACT(v.value,'$.owners'),JSON_ARRAY()),'$[*]' COLUMNS(n FOR ORDINALITY,user_id BIGINT PATH '$')) j WHERE kind='periodic-plans' GROUP BY d.tenant_id,d.id,COALESCE(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(v.value,'$.key')),''),CAST(v.sort_no AS CHAR)),j.user_id;

INSERT INTO eam_inspection_periodic_plan_device_person SELECT d.tenant_id,d.id,COALESCE(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(v.value,'$.key')),''),CAST(v.sort_no AS CHAR)),'reviewer',j.user_id,MIN(j.n) FROM eam_inspection_definition d JOIN JSON_TABLE(COALESCE(JSON_EXTRACT(d.payload,'$.details'),JSON_ARRAY()),'$[*]' COLUMNS(sort_no FOR ORDINALITY,value JSON PATH '$')) v JOIN JSON_TABLE(COALESCE(JSON_EXTRACT(v.value,'$.reviewers'),JSON_ARRAY()),'$[*]' COLUMNS(n FOR ORDINALITY,user_id BIGINT PATH '$')) j WHERE kind='periodic-plans' GROUP BY d.tenant_id,d.id,COALESCE(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(v.value,'$.key')),''),CAST(v.sort_no AS CHAR)),j.user_id;

CREATE TABLE eam_inspection_periodic_plan_device_project (tenant_id BIGINT NOT NULL,plan_id BIGINT NOT NULL,device_key VARCHAR(128) NOT NULL,standard_id BIGINT NOT NULL,item_key VARCHAR(128) NOT NULL,sort_no INT NOT NULL,PRIMARY KEY(tenant_id,plan_id,device_key,standard_id,item_key),FOREIGN KEY(tenant_id,plan_id,device_key) REFERENCES eam_inspection_periodic_plan_device(tenant_id,plan_id,device_key) ON DELETE CASCADE);

INSERT INTO eam_inspection_periodic_plan_device_project SELECT d.tenant_id,d.id,COALESCE(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(v.value,'$.key')),''),CAST(v.sort_no AS CHAR)),j.standard_id,j.item_key,MIN(j.n) FROM eam_inspection_definition d JOIN JSON_TABLE(COALESCE(JSON_EXTRACT(d.payload,'$.details'),JSON_ARRAY()),'$[*]' COLUMNS(sort_no FOR ORDINALITY,value JSON PATH '$')) v JOIN JSON_TABLE(COALESCE(JSON_EXTRACT(v.value,'$.projectRefs'),JSON_ARRAY()),'$[*]' COLUMNS(n FOR ORDINALITY,standard_id BIGINT PATH '$.standardId',item_key VARCHAR(128) PATH '$.itemId')) j WHERE kind='periodic-plans' GROUP BY d.tenant_id,d.id,COALESCE(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(v.value,'$.key')),''),CAST(v.sort_no AS CHAR)),j.standard_id,j.item_key;

CREATE TABLE eam_inspection_daily_rest_day (tenant_id BIGINT NOT NULL,plan_id BIGINT NOT NULL,sort_no INT NOT NULL,day_no INT NOT NULL,PRIMARY KEY(tenant_id,plan_id,sort_no),FOREIGN KEY(plan_id) REFERENCES eam_inspection_daily_plan(id) ON DELETE CASCADE);

INSERT INTO eam_inspection_daily_rest_day SELECT d.tenant_id,d.id,j.sort_no,CAST(j.value AS UNSIGNED) FROM eam_inspection_definition d JOIN JSON_TABLE(COALESCE(JSON_EXTRACT(d.payload,'$.restDays'),JSON_ARRAY()),'$[*]' COLUMNS(sort_no FOR ORDINALITY,value JSON PATH '$')) j WHERE kind='daily-plans';

CREATE TABLE eam_inspection_daily_holiday (tenant_id BIGINT NOT NULL,plan_id BIGINT NOT NULL,sort_no INT NOT NULL,holiday_date DATE NOT NULL,PRIMARY KEY(tenant_id,plan_id,sort_no),FOREIGN KEY(plan_id) REFERENCES eam_inspection_daily_plan(id) ON DELETE CASCADE);

INSERT INTO eam_inspection_daily_holiday SELECT d.tenant_id,d.id,j.sort_no,JSON_UNQUOTE(j.value) FROM eam_inspection_definition d JOIN JSON_TABLE(COALESCE(JSON_EXTRACT(d.payload,'$.holidays'),JSON_ARRAY()),'$[*]' COLUMNS(sort_no FOR ORDINALITY,value JSON PATH '$')) j WHERE kind='daily-plans';

CREATE TABLE eam_inspection_daily_shift (tenant_id BIGINT NOT NULL,plan_id BIGINT NOT NULL,sort_no INT NOT NULL,shift_key VARCHAR(128) NOT NULL,name VARCHAR(150) NOT NULL,start_time TIME NOT NULL,end_time TIME NOT NULL,PRIMARY KEY(tenant_id,plan_id,sort_no),FOREIGN KEY(plan_id) REFERENCES eam_inspection_daily_plan(id) ON DELETE CASCADE);

INSERT INTO eam_inspection_daily_shift SELECT d.tenant_id,d.id,j.sort_no,JSON_UNQUOTE(JSON_EXTRACT(j.value,'$.id')),JSON_UNQUOTE(JSON_EXTRACT(j.value,'$.name')),JSON_UNQUOTE(JSON_EXTRACT(j.value,'$.start')),JSON_UNQUOTE(JSON_EXTRACT(j.value,'$.end')) FROM eam_inspection_definition d JOIN JSON_TABLE(COALESCE(JSON_EXTRACT(d.payload,'$.shifts'),JSON_ARRAY()),'$[*]' COLUMNS(sort_no FOR ORDINALITY,value JSON PATH '$')) j WHERE kind='daily-plans';

CREATE TABLE eam_inspection_daily_roster (tenant_id BIGINT NOT NULL,plan_id BIGINT NOT NULL,sort_no INT NOT NULL,roster_key VARCHAR(128) NOT NULL,roster_date DATE NOT NULL,shift_key VARCHAR(128) NOT NULL,PRIMARY KEY(tenant_id,plan_id,sort_no),FOREIGN KEY(plan_id) REFERENCES eam_inspection_daily_plan(id) ON DELETE CASCADE);

INSERT INTO eam_inspection_daily_roster SELECT d.tenant_id,d.id,j.sort_no,COALESCE(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(j.value,'$.key')),''),CAST(j.sort_no AS CHAR)),JSON_UNQUOTE(JSON_EXTRACT(j.value,'$.date')),JSON_UNQUOTE(JSON_EXTRACT(j.value,'$.shiftId')) FROM eam_inspection_definition d JOIN JSON_TABLE(COALESCE(JSON_EXTRACT(d.payload,'$.roster'),JSON_ARRAY()),'$[*]' COLUMNS(sort_no FOR ORDINALITY,value JSON PATH '$')) j WHERE kind='daily-plans';

CREATE TABLE eam_inspection_daily_roster_user (tenant_id BIGINT NOT NULL,plan_id BIGINT NOT NULL,roster_sort INT NOT NULL,user_id BIGINT NOT NULL,sort_no INT NOT NULL,PRIMARY KEY(tenant_id,plan_id,roster_sort,user_id),FOREIGN KEY(tenant_id,plan_id,roster_sort) REFERENCES eam_inspection_daily_roster(tenant_id,plan_id,sort_no) ON DELETE CASCADE);

INSERT INTO eam_inspection_daily_roster_user SELECT d.tenant_id,d.id,j.n,u.user_id,MIN(u.n) FROM eam_inspection_definition d JOIN JSON_TABLE(COALESCE(JSON_EXTRACT(d.payload,'$.roster'),JSON_ARRAY()),'$[*]' COLUMNS(n FOR ORDINALITY,value JSON PATH '$')) j JOIN JSON_TABLE(COALESCE(JSON_EXTRACT(j.value,'$.users'),JSON_ARRAY()),'$[*]' COLUMNS(n FOR ORDINALITY,user_id BIGINT PATH '$')) u WHERE kind='daily-plans' GROUP BY d.tenant_id,d.id,j.n,u.user_id;

CREATE VIEW v_inspection_item AS SELECT i.*,JSON_OBJECT('id',i.item_key,'code',i.`code`,'name',i.`name`,'content',i.`content`,'typeId',COALESCE(CAST(i.`type_id` AS CHAR),''),'valueType',i.`value_type`,'lower',COALESCE(CAST(i.`lower_bound` AS CHAR),''),'upper',COALESCE(CAST(i.`upper_bound` AS CHAR),''),'required',IF(i.`required`=1,CAST('true' AS JSON),CAST('false' AS JSON)),'photoRequired',IF(i.`photo_required`=1,CAST('true' AS JSON),CAST('false' AS JSON)),'remark',i.`remark`,'options',COALESCE((SELECT JSON_ARRAYAGG(r.option_value) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_inspection_item_option r WHERE r.tenant_id=i.tenant_id AND r.standard_id=i.standard_id AND r.item_key=i.item_key LIMIT 1),JSON_ARRAY()),'normalOptions',COALESCE((SELECT JSON_ARRAYAGG(r.option_value) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_inspection_item_option r WHERE r.tenant_id=i.tenant_id AND r.standard_id=i.standard_id AND r.item_key=i.item_key AND r.normal_value=1 LIMIT 1),JSON_ARRAY()),'references',COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('id',r.file_id,'name',r.name_snapshot,'contentType',r.content_type,'size',r.size_bytes,'url',r.url_snapshot)) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_inspection_item_file r WHERE r.tenant_id=i.tenant_id AND r.standard_id=i.standard_id AND r.item_key=i.item_key LIMIT 1),JSON_ARRAY())) AS item_view FROM eam_inspection_standard_item i;

CREATE VIEW v_inspection_daily_plan_device AS SELECT d.*,JSON_OBJECT('key',d.device_key,'equipmentId',CAST(d.equipment_id AS CHAR),'owners',COALESCE((SELECT JSON_ARRAYAGG(CAST(r.user_id AS CHAR)) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_inspection_daily_plan_device_person r WHERE r.tenant_id=d.tenant_id AND r.plan_id=d.plan_id AND r.device_key=d.device_key AND r.role_code='owner' LIMIT 1),JSON_ARRAY()),'reviewers',COALESCE((SELECT JSON_ARRAYAGG(CAST(r.user_id AS CHAR)) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_inspection_daily_plan_device_person r WHERE r.tenant_id=d.tenant_id AND r.plan_id=d.plan_id AND r.device_key=d.device_key AND r.role_code='reviewer' LIMIT 1),JSON_ARRAY()),'projectRefs',COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('standardId',CAST(r.standard_id AS CHAR),'itemId',r.item_key)) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_inspection_daily_plan_device_project r WHERE r.tenant_id=d.tenant_id AND r.plan_id=d.plan_id AND r.device_key=d.device_key LIMIT 1),JSON_ARRAY())) AS device_view FROM eam_inspection_daily_plan_device d;

CREATE VIEW v_inspection_periodic_plan_device AS SELECT d.*,JSON_OBJECT('key',d.device_key,'equipmentId',CAST(d.equipment_id AS CHAR),'owners',COALESCE((SELECT JSON_ARRAYAGG(CAST(r.user_id AS CHAR)) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_inspection_periodic_plan_device_person r WHERE r.tenant_id=d.tenant_id AND r.plan_id=d.plan_id AND r.device_key=d.device_key AND r.role_code='owner' LIMIT 1),JSON_ARRAY()),'reviewers',COALESCE((SELECT JSON_ARRAYAGG(CAST(r.user_id AS CHAR)) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_inspection_periodic_plan_device_person r WHERE r.tenant_id=d.tenant_id AND r.plan_id=d.plan_id AND r.device_key=d.device_key AND r.role_code='reviewer' LIMIT 1),JSON_ARRAY()),'projectRefs',COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('standardId',CAST(r.standard_id AS CHAR),'itemId',r.item_key)) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_inspection_periodic_plan_device_project r WHERE r.tenant_id=d.tenant_id AND r.plan_id=d.plan_id AND r.device_key=d.device_key LIMIT 1),JSON_ARRAY())) AS device_view FROM eam_inspection_periodic_plan_device d;

CREATE VIEW v_inspection_definition AS SELECT d.id,d.tenant_id,'types' kind,d.code,d.name,d.department_id,d.creator_id,d.row_version,d.created_at,d.updated_at,NULL type_id,JSON_OBJECT('enabled',IF(d.`enabled`=1,CAST('true' AS JSON),CAST('false' AS JSON)),'remark',d.`remark`,'period',d.`period_count`,'unit',d.`period_unit`,'sortOrder',d.`sort_order`,'owners',JSON_ARRAY(),'reviewers',JSON_ARRAY(),'items',JSON_ARRAY(),'equipmentIds',JSON_ARRAY(),'categoryIds',JSON_ARRAY(),'categoryNames',JSON_ARRAY(),'legacyCategoryNames',JSON_ARRAY(),'details',JSON_ARRAY(),'restDays',JSON_ARRAY(),'holidays',JSON_ARRAY(),'shifts',JSON_ARRAY(),'roster',JSON_ARRAY()) payload FROM eam_inspection_type d UNION ALL SELECT d.id,d.tenant_id,'standards' kind,d.code,d.name,d.department_id,d.creator_id,d.row_version,d.created_at,d.updated_at,NULL type_id,JSON_OBJECT('enabled',IF(d.`enabled`=1,CAST('true' AS JSON),CAST('false' AS JSON)),'remark',d.`remark`,'requirement',d.`requirement`,'owners',COALESCE((SELECT JSON_ARRAYAGG(CAST(r.user_id AS CHAR)) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_inspection_standard_person r WHERE r.tenant_id=d.tenant_id AND r.parent_id=d.id AND r.role_code='owner' LIMIT 1),JSON_ARRAY()),'reviewers',COALESCE((SELECT JSON_ARRAYAGG(CAST(r.user_id AS CHAR)) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_inspection_standard_person r WHERE r.tenant_id=d.tenant_id AND r.parent_id=d.id AND r.role_code='reviewer' LIMIT 1),JSON_ARRAY()),'items',COALESCE((SELECT JSON_ARRAYAGG(r.item_view) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM v_inspection_item r WHERE r.tenant_id=d.tenant_id AND r.standard_id=d.id LIMIT 1),JSON_ARRAY()),'equipmentIds',COALESCE((SELECT JSON_ARRAYAGG(CAST(r.equipment_id AS CHAR)) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_inspection_standard_equipment r WHERE r.tenant_id=d.tenant_id AND r.standard_id=d.id LIMIT 1),JSON_ARRAY()),'categoryIds',COALESCE((SELECT JSON_ARRAYAGG(CAST(r.category_id AS CHAR)) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_inspection_standard_category r WHERE r.tenant_id=d.tenant_id AND r.standard_id=d.id LIMIT 1),JSON_ARRAY()),'categoryNames',COALESCE((SELECT JSON_ARRAYAGG(r.name_snapshot) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_inspection_category_label r WHERE r.tenant_id=d.tenant_id AND r.standard_id=d.id AND r.label_kind='display' LIMIT 1),JSON_ARRAY()),'legacyCategoryNames',COALESCE((SELECT JSON_ARRAYAGG(r.name_snapshot) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_inspection_category_label r WHERE r.tenant_id=d.tenant_id AND r.standard_id=d.id AND r.label_kind='legacy' LIMIT 1),JSON_ARRAY()),'details',JSON_ARRAY(),'restDays',JSON_ARRAY(),'holidays',JSON_ARRAY(),'shifts',JSON_ARRAY(),'roster',JSON_ARRAY()) payload FROM eam_inspection_standard d UNION ALL SELECT d.id,d.tenant_id,'daily-plans' kind,d.code,d.name,d.department_id,d.creator_id,d.row_version,d.created_at,d.updated_at,d.type_id type_id,JSON_OBJECT('enabled',IF(d.`enabled`=1,CAST('true' AS JSON),CAST('false' AS JSON)),'remark',d.`remark`,'typeId',COALESCE(CAST(d.`type_id` AS CHAR),''),'reviewMode',d.`review_mode`,'startDate',COALESCE(DATE_FORMAT(d.`start_date`,'%Y-%m-%d'),''),'endDate',COALESCE(DATE_FORMAT(d.`end_date`,'%Y-%m-%d'),''),'validHours',d.`valid_duration`,'advanceHours',d.`advance_duration`,'remindHours',d.`remind_duration`,'expireRemindHours',d.`expire_remind_duration`,'validUnit',d.`valid_unit`,'advanceUnit',d.`advance_unit`,'remindUnit',d.`remind_unit`,'expireRemindUnit',d.`expire_remind_unit`,'scanMode',d.`scan_mode`,'onlyAbnormal',IF(d.`only_abnormal`=1,CAST('true' AS JSON),CAST('false' AS JSON)),'randomPhotoCount',d.`random_photo_count`,'allowLate',IF(d.`allow_late`=1,CAST('true' AS JSON),CAST('false' AS JSON)),'personMode',d.`person_mode`,'skipUnstaffed',IF(d.`skip_unstaffed`=1,CAST('true' AS JSON),CAST('false' AS JSON)),'restCycle',d.`rest_cycle`,'useShiftEnd',IF(d.`use_shift_end`=1,CAST('true' AS JSON),CAST('false' AS JSON)),'owners',COALESCE((SELECT JSON_ARRAYAGG(CAST(r.user_id AS CHAR)) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_inspection_daily_plan_person r WHERE r.tenant_id=d.tenant_id AND r.parent_id=d.id AND r.role_code='owner' LIMIT 1),JSON_ARRAY()),'reviewers',COALESCE((SELECT JSON_ARRAYAGG(CAST(r.user_id AS CHAR)) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_inspection_daily_plan_person r WHERE r.tenant_id=d.tenant_id AND r.parent_id=d.id AND r.role_code='reviewer' LIMIT 1),JSON_ARRAY()),'items',JSON_ARRAY(),'equipmentIds',JSON_ARRAY(),'categoryIds',JSON_ARRAY(),'categoryNames',JSON_ARRAY(),'legacyCategoryNames',JSON_ARRAY(),'details',COALESCE((SELECT JSON_ARRAYAGG(r.device_view) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM v_inspection_daily_plan_device r WHERE r.tenant_id=d.tenant_id AND r.plan_id=d.id LIMIT 1),JSON_ARRAY()),'restDays',COALESCE((SELECT JSON_ARRAYAGG(r.day_no) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_inspection_daily_rest_day r WHERE r.tenant_id=d.tenant_id AND r.plan_id=d.id LIMIT 1),JSON_ARRAY()),'holidays',COALESCE((SELECT JSON_ARRAYAGG(DATE_FORMAT(r.holiday_date,'%Y-%m-%d')) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_inspection_daily_holiday r WHERE r.tenant_id=d.tenant_id AND r.plan_id=d.id LIMIT 1),JSON_ARRAY()),'shifts',COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('id',r.shift_key,'name',r.name,'start',TIME_FORMAT(r.start_time,'%H:%i'),'end',TIME_FORMAT(r.end_time,'%H:%i'))) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_inspection_daily_shift r WHERE r.tenant_id=d.tenant_id AND r.plan_id=d.id LIMIT 1),JSON_ARRAY()),'roster',COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('key',r.roster_key,'date',DATE_FORMAT(r.roster_date,'%Y-%m-%d'),'shiftId',r.shift_key,'users',COALESCE((SELECT JSON_ARRAYAGG(CAST(u.user_id AS CHAR)) OVER(ORDER BY u.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_inspection_daily_roster_user u WHERE u.tenant_id=r.tenant_id AND u.plan_id=r.plan_id AND u.roster_sort=r.sort_no LIMIT 1),JSON_ARRAY()))) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_inspection_daily_roster r WHERE r.tenant_id=d.tenant_id AND r.plan_id=d.id LIMIT 1),JSON_ARRAY())) payload FROM eam_inspection_daily_plan d UNION ALL SELECT d.id,d.tenant_id,'periodic-plans' kind,d.code,d.name,d.department_id,d.creator_id,d.row_version,d.created_at,d.updated_at,d.type_id type_id,JSON_OBJECT('enabled',IF(d.`enabled`=1,CAST('true' AS JSON),CAST('false' AS JSON)),'remark',d.`remark`,'typeId',COALESCE(CAST(d.`type_id` AS CHAR),''),'reviewMode',d.`review_mode`,'startDate',COALESCE(DATE_FORMAT(d.`start_date`,'%Y-%m-%d'),''),'endDate',COALESCE(DATE_FORMAT(d.`end_date`,'%Y-%m-%d'),''),'validHours',d.`valid_duration`,'advanceHours',d.`advance_duration`,'remindHours',d.`remind_duration`,'expireRemindHours',d.`expire_remind_duration`,'validUnit',d.`valid_unit`,'advanceUnit',d.`advance_unit`,'remindUnit',d.`remind_unit`,'expireRemindUnit',d.`expire_remind_unit`,'scanMode',d.`scan_mode`,'onlyAbnormal',IF(d.`only_abnormal`=1,CAST('true' AS JSON),CAST('false' AS JSON)),'randomPhotoCount',d.`random_photo_count`,'allowLate',IF(d.`allow_late`=1,CAST('true' AS JSON),CAST('false' AS JSON)),'period',d.`period_count`,'unit',d.`period_unit`,'nextAt',COALESCE(DATE_FORMAT(d.`next_at`,'%Y-%m-%dT%H:%i:%s'),''),'owners',COALESCE((SELECT JSON_ARRAYAGG(CAST(r.user_id AS CHAR)) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_inspection_periodic_plan_person r WHERE r.tenant_id=d.tenant_id AND r.parent_id=d.id AND r.role_code='owner' LIMIT 1),JSON_ARRAY()),'reviewers',COALESCE((SELECT JSON_ARRAYAGG(CAST(r.user_id AS CHAR)) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_inspection_periodic_plan_person r WHERE r.tenant_id=d.tenant_id AND r.parent_id=d.id AND r.role_code='reviewer' LIMIT 1),JSON_ARRAY()),'items',JSON_ARRAY(),'equipmentIds',JSON_ARRAY(),'categoryIds',JSON_ARRAY(),'categoryNames',JSON_ARRAY(),'legacyCategoryNames',JSON_ARRAY(),'details',COALESCE((SELECT JSON_ARRAYAGG(r.device_view) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM v_inspection_periodic_plan_device r WHERE r.tenant_id=d.tenant_id AND r.plan_id=d.id LIMIT 1),JSON_ARRAY()),'restDays',JSON_ARRAY(),'holidays',JSON_ARRAY(),'shifts',JSON_ARRAY(),'roster',JSON_ARRAY()) payload FROM eam_inspection_periodic_plan d;

